import json
import re
from docx import Document

def fill_template(template_path, data_path, output_path):
    # Load data
    with open(data_path, 'r') as f:
        data = json.load(f)

    # Load template
    doc = Document(template_path)

    def replace_in_paragraph(para, data):
        text = para.text
        # Find all {{KEY}} placeholders
        pattern = r'\{\{([A-Z_]+)\}\}'
        matches = re.findall(pattern, text)

        if not matches:
            return False

        new_text = text
        for key in matches:
            placeholder = '{{' + key + '}}'
            if key in data:
                new_text = new_text.replace(placeholder, str(data[key]))

        if new_text != text:
            # Preserve first run's formatting, clear others
            if para.runs:
                para.runs[0].text = new_text
                for run in para.runs[1:]:
                    run.text = ''
            else:
                para.text = new_text
            return True
        return False

    def process_all_elements(doc, data):
        # 1. Handle Conditional Section (IF_RELOCATION)
        # We'll search for {{IF_RELOCATION}} and {{END_IF_RELOCATION}}
        # This implementation assumes they might span multiple paragraphs or be in the same one.

        include_relocation = data.get('RELOCATION_PACKAGE') == 'Yes'

        all_paras = []
        # Gather all paragraphs from main document
        for para in doc.paragraphs:
            all_paras.append(para)

        # Also check tables for markers (though usually markers are in main text)
        for table in doc.tables:
            for row in table.rows:
                for cell in row.cells:
                    for para in cell.paragraphs:
                        all_paras.append(para)

        start_marker = '{{IF_RELOCATION}}'
        end_marker = '{{END_IF_RELOCATION}}'

        found_start = -1
        found_end = -1

        for i, para in enumerate(all_paras):
            if start_marker in para.text:
                found_start = i
            if end_marker in para.text:
                found_end = i

        if found_start != -1 and found_end != -1:
            if include_relocation:
                # Keep content, remove markers
                # Start marker paragraph
                para_start = all_paras[found_start]
                para_start.text = para_start.text.replace(start_marker, '')
                # End marker paragraph
                para_end = all_paras[found_end]
                para_end.text = para_end.text.replace(end_marker, '')
            else:
                # Remove everything between and including markers
                if found_start == found_end:
                    # Same paragraph
                    para = all_paras[found_start]
                    # Simple regex to remove between markers
                    para.text = re.sub(re.escape(start_marker) + '.*?' + re.escape(end_marker), '', para.text)
                else:
                    # Different paragraphs
                    # Clear paragraphs in between
                    for i in range(found_start + 1, found_end):
                        all_paras[i].text = ''
                    # Handle start and end paragraphs
                    # We'll remove text from start_marker to the end of start paragraph
                    para_start = all_paras[found_start]
                    idx_s = para_start.text.find(start_marker)
                    para_start.text = para_start.text[:idx_s]

                    # We'll remove text from beginning of end paragraph to end_marker
                    para_end = all_paras[found_end]
                    idx_e = para_end.text.find(end_marker)
                    para_end.text = para_end.text[idx_e + len(end_marker):]

        # 2. Process all placeholders
        for para in doc.paragraphs:
            replace_in_paragraph(para, data)

        for table in doc.tables:
            for row in table.rows:
                for cell in row.cells:
                    for para in cell.paragraphs:
                        replace_in_paragraph(para, data)
                    # Nested tables
                    for nested_table in cell.tables:
                        for n_row in nested_table.rows:
                            for n_cell in n_row.cells:
                                for n_para in n_cell.paragraphs:
                                    replace_in_paragraph(n_para, data)

        for section in doc.sections:
            for para in section.header.paragraphs:
                replace_in_paragraph(para, data)
            for para in section.footer.paragraphs:
                replace_in_paragraph(para, data)

    process_all_elements(doc, data)
    doc.save(output_path)

if __name__ == "__main__":
    fill_template('offer_letter_template.docx', 'employee_data.json', 'offer_letter_filled.docx')

